40	// reuseUnixSocket copies and reuses the unix domain socket (UDS) if we already
41	// have it open; if not, unlink it so we can have it.
42	// No-op if not a unix network.
43	func reuseUnixSocket(network, addr string) (any, error) {
44		socketKey := listenerKey(network, addr)
45	
46		socket, exists := unixSockets[socketKey]
47		if exists {
48			// make copy of file descriptor
49			socketFile, err := socket.File() // does dup() deep down
50			if err != nil {
51				return nil, err
52			}
53	
54			// use copied fd to make new Listener or PacketConn, then replace
55			// it in the map so that future copies always come from the most
56			// recent fd (as the previous ones will be closed, and we'd get
57			// "use of closed network connection" errors) -- note that we
58			// preserve the *pointer* to the counter (not just the value) so
59			// that all socket wrappers will refer to the same value
60			switch unixSocket := socket.(type) {
61			case *unixListener:
62				ln, err := net.FileListener(socketFile)
63				if err != nil {
64					return nil, err
65				}
66				unixSocket.count.Add(1)
67				unixSockets[socketKey] = &unixListener{ln.(*net.UnixListener), socketKey, unixSocket.count}
68	
69			case *unixConn:
70				pc, err := net.FilePacketConn(socketFile)
71				if err != nil {
72					return nil, err
73				}
74				unixSocket.count.Add(1)
75				unixSockets[socketKey] = &unixConn{pc.(*net.UnixConn), socketKey, unixSocket.count}
76			}
77	
78			return unixSockets[socketKey], nil
79		}
