266	// isBidirectionalStream returns whether we should work in bi-directional stream mode.
267	//
268	// See https://github.com/caddyserver/caddy/pull/3620 for discussion of nuances.
269	func (h Handler) isBidirectionalStream(req *http.Request, res *http.Response) bool {
270		// We have to check the encoding here; only flush headers with identity encoding.
271		// Non-identity encoding might combine with "encode" directive, and in that case,
272		// if body size larger than enc.MinLength, upper level encode handle might have
273		// Content-Encoding header to write.
274		// (see https://github.com/caddyserver/caddy/issues/3606 for use case)
275		ae := req.Header.Get("Accept-Encoding")
276	
277		return req.ProtoMajor == 2 &&
278			res.ProtoMajor == 2 &&
279			res.ContentLength == -1 &&
280			(ae == "identity" || ae == "")
281	}
