458	// writeCloseControl sends a best-effort Close control message to the given
459	// WebSocket connection. Thanks to @pascaldekloe who provided inspiration
460	// from his simple implementation of this I was able to learn from at:
461	// github.com/pascaldekloe/websocket. Further work for handling masking
462	// taken from github.com/gorilla/websocket.
463	func writeCloseControl(conn io.Writer, isClient bool) error {
464		// Sources:
465		// https://github.com/pascaldekloe/websocket/blob/32050af67a5d/websocket.go#L119
466		// https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L413
467	
468		// For now, we're not using a reason. We might later, though.
469		// The code handling the reason is left in
470		var reason string // max 123 bytes (control frame payload limit is 125; status code takes 2)
471	
472		const closeMessage = 8
473		const finalBit = 1 << 7 // Frame header byte 0 bits from Section 5.2 of RFC 6455
474		const maskBit = 1 << 7  // Frame header byte 1 bits from Section 5.2 of RFC 6455
475		const goingAwayUpper uint8 = 1001 >> 8
476		const goingAwayLower uint8 = 1001 & 0xff
477	
478		b0 := byte(closeMessage) | finalBit
479		b1 := byte(len(reason) + 2)
480		if isClient {
481			b1 |= maskBit
482		}
483	
484		buf := make([]byte, 0, 127)
485		buf = append(buf, b0, b1)
486		msgLength := 4 + len(reason)
487	
488		// Both branches below append the "going away" code and reason
489		appendMessage := func(buf []byte) []byte {
490			buf = append(buf, goingAwayUpper, goingAwayLower)
491			buf = append(buf, []byte(reason)...)
492			return buf
493		}
494	
495		// When we're the client, we need to mask the message as per
496		// https://www.rfc-editor.org/rfc/rfc6455#section-5.3
497		if isClient {
498			key := newMaskKey()
499			buf = append(buf, key[:]...)
500			msgLength += len(key)
501			buf = appendMessage(buf)
502			maskBytes(key, 0, buf[2+len(key):])
503		} else {
504			buf = appendMessage(buf)
505		}
506	
507		// simply best-effort, but return error for logging purposes
508		// TODO: we might need to ensure we are the exclusive writer by this point (io.Copy is stopped)?
509		_, err := conn.Write(buf[:msgLength])
510		return err
511	}
512	
513	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/mask.go
514	func maskBytes(key [4]byte, pos int, b []byte) int {
515		// Mask one byte at a time for small buffers.
516		if len(b) < 2*wordSize {
517			for i := range b {
518				b[i] ^= key[pos&3]
519				pos++
520			}
521			return pos & 3
522		}
523	
524		// Mask one byte at a time to word boundary.
525		if n := int(uintptr(unsafe.Pointer(&b[0]))) % wordSize; n != 0 {
526			n = wordSize - n
527			for i := range b[:n] {
528				b[i] ^= key[pos&3]
529				pos++
530			}
531			b = b[n:]
532		}
533	
534		// Create aligned word size key.
535		var k [wordSize]byte
536		for i := range k {
537			k[i] = key[(pos+i)&3] // nolint:gosec // false positive, impossible to be out of bounds; see: https://github.com/securego/gosec/issues/1525
538		}
539		kw := *(*uintptr)(unsafe.Pointer(&k))
540	
541		// Mask one word at a time.
542		n := (len(b) / wordSize) * wordSize
543		for i := 0; i < n; i += wordSize {
544			*(*uintptr)(unsafe.Add(unsafe.Pointer(&b[0]), i)) ^= kw
545		}
546	
547		// Mask one byte at a time for remaining bytes.
548		b = b[n:]
549		for i := range b {
550			b[i] ^= key[pos&3]
551			pos++
552		}
553	
554		return pos & 3
555	}
556	
557	// Copied from https://github.com/gorilla/websocket/blob/v1.5.0/conn.go#L184
558	func newMaskKey() [4]byte {
559		n := weakrand.Uint32()
560		return [4]byte{byte(n), byte(n >> 8), byte(n >> 16), byte(n >> 24)}
561	}
562	
563	// isWebsocket returns true if r looks to be an upgrade request for WebSockets.
564	// It is a fairly naive check.
565	func isWebsocket(r *http.Request) bool {
566		return httpguts.HeaderValuesContainsToken(r.Header["Connection"], "upgrade") &&
567			httpguts.HeaderValuesContainsToken(r.Header["Upgrade"], "websocket")
568	}
569	
570	// openConnection maps an open connection to
571	// an optional function for graceful close.
572	type openConnection struct {
573		conn          io.ReadWriteCloser
574		gracefulClose func() error
575	}
576	
577	type maxLatencyWriter struct {
578		dst     io.Writer
579		flush   func() error
580		latency time.Duration // non-zero; negative means to flush immediately
581	
582		mu           sync.Mutex // protects t, flushPending, and dst.Flush
583		t            *time.Timer
584		flushPending bool
585		logger       *zap.Logger
586	}
587	
588	func (m *maxLatencyWriter) Write(p []byte) (n int, err error) {
589		m.mu.Lock()
590		defer m.mu.Unlock()
591		n, err = m.dst.Write(p)
592		if c := m.logger.Check(zapcore.DebugLevel, "wrote bytes"); c != nil {
593			c.Write(zap.Int("n", n), zap.Error(err))
594		}
595		if m.latency < 0 {
596			m.logger.Debug("flushing immediately")
597			//nolint:errcheck
598			m.flush()
599			return n, err
600		}
601		if m.flushPending {
602			m.logger.Debug("delayed flush already pending")
603			return n, err
604		}
605		if m.t == nil {
606			m.t = time.AfterFunc(m.latency, m.delayedFlush)
607		} else {
608			m.t.Reset(m.latency)
609		}
610		if c := m.logger.Check(zapcore.DebugLevel, "timer set for delayed flush"); c != nil {
611			c.Write(zap.Duration("duration", m.latency))
612		}
613		m.flushPending = true
614		return n, err
615	}
616	
617	func (m *maxLatencyWriter) delayedFlush() {
618		m.mu.Lock()
619		defer m.mu.Unlock()
620		if !m.flushPending { // if stop was called but AfterFunc already started this goroutine
621			m.logger.Debug("delayed flush is not pending")
622			return
623		}
624		m.logger.Debug("delayed flush")
625		//nolint:errcheck
626		m.flush()
627		m.flushPending = false
628	}
629	
630	func (m *maxLatencyWriter) stop() {
631		m.mu.Lock()
632		defer m.mu.Unlock()
633		m.flushPending = false
634		if m.t != nil {
635			m.t.Stop()
636		}
637	}
638	
639	// switchProtocolCopier exists so goroutines proxying data back and
640	// forth have nice names in stacks.
641	type switchProtocolCopier struct {
642		user, backend io.ReadWriteCloser
643		wg            *sync.WaitGroup
644		bufferSize    int
645	}
646	
647	func (c switchProtocolCopier) copyFromBackend(errc chan<- error) {
648		_, err := io.CopyBuffer(c.user, c.backend, c.buffer())
649		errc <- err
650		c.wg.Done()
651	}
652	
653	func (c switchProtocolCopier) copyToBackend(errc chan<- error) {
654		_, err := io.CopyBuffer(c.backend, c.user, c.buffer())
655		errc <- err
656		c.wg.Done()
657	}
658	
659	func (c switchProtocolCopier) buffer() []byte {
660		size := c.bufferSize
661		if size <= 0 {
662			size = defaultBufferSize
663		}
664		return make([]byte, size)
665	}
666	
667	var streamingBufPool = sync.Pool{
668		New: func() any {
669			// The Pool's New function should generally only return pointer
670			// types, since a pointer can be put into the return interface
671			// value without an allocation
672			// - (from the package docs)
673			b := make([]byte, defaultBufferSize)
674			return &b
675		},
676	}
677	
678	const (
679		defaultBufferSize = 32 * 1024
680		wordSize          = int(unsafe.Sizeof(uintptr(0)))
681	)
682

