// switchJSONConfig builds a complete configuration with two listeners on
// fixed addresses: a plaintext HTTP/1.1 site and an HTTPS site using the
// internal issuer negotiated as HTTP/2. Variant A proxies /stream to the
// upstream; variant B only serves /version. A and B listen on exactly the
// same addresses, which is what makes the switch boundary observable.
func switchJSONConfig(adminAddr, h1Addr, h2Addr, upstreamAddr, variant string) string {
	statusA, statusB := 201, 202
	_ = statusB
	versionBody := map[string]string{"A": versionABody, "B": versionBBody}
	status := map[string]int{"A": statusA, "B": http.StatusAccepted}

	streamRoute := ""
	if variant == "A" {
		streamRoute = fmt.Sprintf(`
						,{
							"match": [{"path": ["/stream"]}],
							"handle": [{
								"handler": "reverse_proxy",
								"headers": {"request": {"set": {"X-Variant": ["A"]}}},
								"upstreams": [{"dial": %q}]
							}]
						}`, upstreamAddr)
	}

	// h2Addr is a host:port whose host is "localhost" for the TLS site.
	h2Port := strings.Split(h2Addr, ":")[1]

	return fmt.Sprintf(`{
	"admin": {"listen": %q},
	"apps": {
		"http": {
			"grace_period": "60s",
			"servers": {
				"h1": {
					"listen": [%q],
					"routes": [
						{
							"match": [{"path": ["/version"]}],
							"handle": [{
								"handler": "static_response",
								"status_code": %d,
								"headers": {"X-Variant": [%q]},
								"body": %q
							}]
						}%s
					]
				},
				"h2": {
					"listen": [%q],
					"routes": [
						{
							"match": [{"path": ["/version"]}],
							"handle": [{
								"handler": "static_response",
								"status_code": %d,
								"headers": {"X-Variant": [%q]},
								"body": %q
							}]
						}%s
					]
				}
			}
		},
		"pki": {
			"certificate_authorities": {
				"local": {"install_trust": false}
			}
		},
		"tls": {
			"automation": {
				"policies": [
					{
						"subjects": ["localhost"],
						"issuers": [{"module": "internal"}]
					}
				]
			}
		}
	}
}`,
		adminAddr,
		h1Addr, status[variant], variant, versionBody[variant], streamRoute,
		":"+h2Port, status[variant], variant, versionBody[variant], streamRoute)
}

