	var status int
	var respBody string
	go func() {
		defer close(done)
		status, respBody = postLoad(t, adminURL, "application/json", strings.NewReader(body))
	}()
	select {
	case <-done:
	case <-time.After(10 * time.Second):
		t.Fatalf("%s: POST /load with unparseable JSON did not fail in bounded time", label)
	}
	if status != http.StatusBadRequest {
		t.Fatalf("%s: POST /load status: got %d, want 400; body: %s", label, status, respBody)
	}
	if !strings.Contains(respBody, "decoding request body") {
		t.Fatalf("%s: POST /load error: got %q, want a JSON decoding error", label, respBody)
	}
}

