// waitForVariant polls /version with fresh connections until the site answers
// want (status, X-Variant and body), or the deadline expires. It tolerates the
// transient TLS/connection errors of an internal certificate being minted.
func waitForVariant(t *testing.T, baseURL string, h2 bool, want versionExpectation, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	var lastErr string
	for time.Now().Before(deadline) {
		client := newFailoverClient(h2)
		client.Timeout = 5 * time.Second
		resp, err := client.Get(baseURL + "/version")
		if err != nil {
			lastErr = err.Error()
			time.Sleep(100 * time.Millisecond)
			continue
		}
		bodyBytes, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		if resp.StatusCode == want.status &&
			resp.Header.Get("X-Variant") == want.variant &&
			string(bodyBytes) == want.body {
			return
		}
		lastErr = fmt.Sprintf("status=%d variant=%q body=%q", resp.StatusCode, resp.Header.Get("X-Variant"), bodyBytes)
		time.Sleep(100 * time.Millisecond)
	}
	t.Fatalf("%s never answered variant %s within %s (last: %s)\n%s",
		baseURL, want.variant, timeout, lastErr, caddyLogTail(t))
}

// caddyLogTail returns the running instance log for startup diagnostics.
func caddyLogTail(t *testing.T) string {
	t.Helper()
	if runningCaddyLogPath == "" {
		return ""
	}
	b, err := os.ReadFile(runningCaddyLogPath)
	if err != nil {
		return ""
	}
	const max = 2000
	if len(b) > max {
		b = b[len(b)-max:]
	}
	return string(b)
}

