	for conn, state := range d.states {
		if state == http.StateNew {
			freshConns = append(freshConns, conn)
		}
	}
	d.mu.Unlock()

	// drop connections accepted before the fence that never produced a
	// request: nothing is in flight on them, so closing makes the client
	// reconnect to the new instance without losing any response
	for _, conn := range freshConns {
		_ = conn.Close()
	}

	// ensure every wrapped listener has stopped accepting before the fence is
	// considered reached (Shutdown closes them just before invoking this hook)
	d.mu.Lock()
	listeners := append([]*drainListener(nil), d.listeners...)
	d.mu.Unlock()
	for _, ln := range listeners {
		ln.waitAcceptors()
	}

	d.fenceOnce.Do(func() { close(d.fenceReached) })
