	net.Listener

	closeOnce sync.Once
	closeErr  error

	// acceptors tracks outstanding Accept calls: incremented before Accept
	// blocks and decremented after it returns.
	acceptors sync.WaitGroup
}

func (l *drainListener) Accept() (net.Conn, error) {
	l.acceptors.Add(1)
	defer l.acceptors.Done()
	return l.Listener.Accept()
}

func (l *drainListener) waitAcceptors() { l.acceptors.Wait() }

// Close is idempotent: the drain fence closes the listener through
// http.Server.Shutdown and the server may also close it during teardown.
func (l *drainListener) Close() error {
	l.closeOnce.Do(func() {
		l.closeErr = l.Listener.Close()
	})
	// after the underlying listener is closed, a blocked Accept returns
	// promptly; wait for it so a connection can never be dispatched after the
	// fence considers accepting stopped
	l.acceptors.Wait()
	return l.closeErr
