package caddyhttp

import (
	"context"
	"net"
	"net/http"
	"sync"
	"time"

	"go.uber.org/zap"
)

// drainFenceTimeout bounds how long a configuration switch waits for an old
// server to reach the point at which it provably no longer admits new work.
// Closing the listeners (the strongest guarantee) is synchronous and is not
// subject to this timeout; this only covers the server-internal shutdown
// handshake (such as broadcasting HTTP/2 GOAWAY), which is immediate on a
// healthy loopback connection. It exists solely so a wedged server cannot make
// POST /load hang forever.
const drainFenceTimeout = 5 * time.Second

// drainController makes the instant an old HTTP server stops admitting new
// connections and requests deterministic across a configuration switch.
//
// The plain net/http.Server.Shutdown is not enough by itself: even after it
// returns, its effect on listeners and keep-alive connections only becomes
// observable asynchronously, and Caddy historically only waited for the
// shutdown goroutine to be scheduled - which could happen before Shutdown had
// closed a single listener. This controller performs the admission shutdown up
// front and waits for each of its steps to actually take effect:
//
//  1. every listener is closed and the call blocks until each blocked Accept
//     has returned, so the old server can never hand out another connection;
//  2. HTTP/1.x keep-alives are disabled, which closes idle connections at once
//     and makes a response that is already in flight the last one its
//     connection serves (the net/http server checks this synchronously before
//     processing any further request, including one already buffered);
//  3. connections that were accepted but never produced a request are closed,
//     as they carry no in-flight response and the client reconnects to the
//     new instance transparently;
//  4. the graceful Shutdown runs in the background: it broadcasts HTTP/2
//     GOAWAY (after which new multiplexed streams are refused) and keeps
//     serving responses that were already in flight until they complete or
//     the grace period expires.
//
// beginDrain returns once steps 1-3 are finished and step 4 has provably
// started. In-flight responses are never waited on here (and never cut short
// before the grace period); the returned channel closes when the background
// shutdown has fully completed.
type drainController struct {
	// once makes the drain idempotent: Stop may be reached more than once via
	// Cleanup on a partially started server.
	once sync.Once

	mu        sync.Mutex
	listeners []*drainListener
	states    map[net.Conn]http.ConnState

	// shutdownBegun is closed from the http.Server's OnShutdown hook, proving
	// that Shutdown ran past listener teardown and is broadcasting GOAWAY.
	begunOnce      sync.Once
	shutdownBegun  chan struct{}
	shutdownDone   chan struct{}
	shutdownDoneMu sync.Mutex
}

func newDrainController() *drainController {
	return &drainController{
		states:       make(map[net.Conn]http.ConnState),
		shutdownBegun: make(chan struct{}),
	}
}

// wrapListener makes ln report its Accept lifecycle and accepted connections
// to the controller, so a drain can prove that accepting new connections has
// stopped. The returned listener otherwise behaves exactly like ln and does
// not modify accepted connections (it must stay transparent because the
// standard library dispatches TLS HTTP/2 based on the concrete *tls.Conn
// type).
func (d *drainController) wrapListener(ln net.Listener) *drainListener {
	dl := &drainListener{Listener: ln, controller: d}
	d.mu.Lock()
	d.listeners = append(d.listeners, dl)
	d.mu.Unlock()
	return dl
}

// connState tracks connection state via the server's ConnState hook. HTTP/1
// connections report New/Active/Idle/Closed; HTTP/2 connections report
// Active/Idle directly from the HTTP/2 implementation.
func (d *drainController) connState(conn net.Conn, state http.ConnState) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if state == http.StateClosed {
		delete(d.states, conn)
		return
	}
	d.states[conn] = state
}

// markShutdownBegun is registered on the http.Server and invoked from
// Shutdown after its listeners are already torn down and its HTTP/2 graceful
// shutdown is being broadcast.
func (d *drainController) markShutdownBegun() {
	d.begunOnce.Do(func() { close(d.shutdownBegun) })
}

// beginDrain performs the deterministic admission fence described on the type
// and then lets server.Shutdown finish (waiting for in-flight responses) in
// the background. It is safe to call multiple times; only the first call runs
// the fence. The returned channel is closed once the background shutdown fully
// completes (all in-flight responses finished or graceCtx expired).
func (d *drainController) beginDrain(server *http.Server, graceCtx context.Context, logger *zap.Logger) <-chan struct{} {
	d.once.Do(func() {
		d.shutdownDoneMu.Lock()
		d.shutdownDone = make(chan struct{})
		d.shutdownDoneMu.Unlock()

		go func() {
			defer close(d.shutdownDone)
			d.runFence(server, graceCtx, logger)
		}()
	})

	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	return done
}

// waitFenceReady blocks until the admission fence has been reached - listeners
// closed, keep-alives disabled and the graceful shutdown provably started - or
// the timeout elapses.
func (d *drainController) waitFenceReady(logger *zap.Logger) {
	timer := time.NewTimer(drainFenceTimeout)
	defer timer.Stop()
	select {
	case <-d.shutdownBegun:
	case <-timer.C:
		// listener teardown (the guarantee that no new connections are
		// accepted) is synchronous and already complete, so a timeout here
		// only means the internal shutdown handshake took unexpectedly long;
		// log it and proceed rather than hang the configuration switch
		if logger != nil {
			logger.Error("timed out waiting for old server to finish its shutdown handshake; "+
				"it is no longer accepting connections but may briefly still be draining",
				zap.Duration("timeout", drainFenceTimeout))
		}
	}
}

// waitShutdownDone blocks until the background shutdown of every drained
// server completes. It is used when the process is exiting, which is the only
// time in-flight responses are waited on synchronously.
func (d *drainController) waitShutdownDone() {
	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	if done != nil {
		<-done
	}
}

func (d *drainController) runFence(server *http.Server, graceCtx context.Context, logger *zap.Logger) {
	// Step 1: stop accepting. Closing the listener unblocks every pending
	// Accept with an error; waiting for those Accept calls to return proves
	// that no further connection can be dispatched to this server.
	d.mu.Lock()
	listeners := append([]*drainListener(nil), d.listeners...)
	d.mu.Unlock()
	for _, ln := range listeners {
		ln.closeAndWait()
	}

	// Step 2: disable keep-alives. Idle HTTP/1 connections are closed at once;
	// a request already in flight stays the final request on its connection.
	server.SetKeepAlivesEnabled(false)

	// Step 3: drop half-open connections that never reached a request. They
	// predate the switch but carry nothing in flight, so closing them makes
	// the client reconnect to the new instance without losing any response.
	d.mu.Lock()
	var freshConns []net.Conn
	for conn, state := range d.states {
		if state == http.StateNew {
			freshConns = append(freshConns, conn)
		}
	}
	d.mu.Unlock()
	for _, conn := range freshConns {
		_ = conn.Close()
	}

	// Step 4: graceful shutdown in the background-of-this-goroutine. Closing
	// the (already closed) listeners is a no-op; Shutdown broadcasts HTTP/2
	// GOAWAY via the OnShutdown hook - which closes shutdownBegun - and then
	// waits for in-flight HTTP/1 responses until graceCtx. It does not return
	// until they finish, keeping the old server alive for them.
	if err := server.Shutdown(graceCtx); err != nil {
		if cause := context.Cause(graceCtx); cause != nil && err == context.DeadlineExceeded {
			err = cause
		}
		if logger != nil {
			logger.Error("server shutdown", zap.Error(err))
		}
	}
}

// drainListener is a net.Listener whose Close is synchronized with in-flight
// Accept calls, allowing a drain to block until accepting has stopped.
type drainListener struct {
	net.Listener
	controller *drainController

	closeOnce sync.Once
	closeErr  error

	// accepting tracks outstanding Accept calls. It is incremented by each
	// Accept before it blocks and decremented when Accept returns; Close
	// waits on it so a successful connection can never be handed out after
	// the drain considered accepting stopped.
	accepting sync.WaitGroup
}

func (l *drainListener) Accept() (net.Conn, error) {
	l.accepting.Add(1)
	conn, err := l.Listener.Accept()
	l.accepting.Done()
	return conn, err
}

func (l *drainListener) closeAndWait() {
	l.closeOnce.Do(func() {
		l.closeErr = l.Listener.Close()
	})
	l.accepting.Wait()
}

// Close is called both by the drain fence and, later, by http.Server.Shutdown
// closing its tracked listeners; it must be idempotent.
func (l *drainListener) Close() error {
	l.closeAndWait()
	return l.closeErr
}

