package caddyhttp

import (
	"context"
	"net"
	"net/http"
	"sync"
	"time"

	"go.uber.org/zap"
)

// drainFenceTimeout bounds how long a configuration switch waits for an old
// server to reach the point at which it provably no longer admits new work.
// Closing the listeners (the strongest guarantee) is synchronous inside
// http.Server.Shutdown and is not subject to this timeout; the timeout only
// guards the bookkeeping performed afterwards, so a wedged server cannot make
// POST /load hang forever.
const drainFenceTimeout = 5 * time.Second

// drainController makes the instant an old HTTP server stops admitting new
// connections and requests deterministic across a configuration switch.
//
// http.Server.Shutdown performs the right actions, but Caddy historically
// waited merely for the shutdown goroutine to be scheduled - which could
// happen before Shutdown had set its shutdown flag or closed a single
// listener. This controller turns that into an explicit fence by wrapping
// every listener so Close blocks until each in-flight Accept has returned:
//
//   - http.Server.Shutdown sets its shutdown flag and then synchronously
//     closes its listeners. By the time a wrapped listener's Close returns,
//     the shutdown flag is already set, so an HTTP/1 keep-alive connection
//     serves at most the response already in flight - the net/http server
//     checks the flag synchronously before processing any further request,
//     including one already buffered - and the server cannot hand out another
//     connection, so every new connection to the reused socket reaches the
//     new server.
//   - connections accepted before the fence that never produced a request are
//     closed: nothing is in flight on them, so the client transparently
//     reconnects to the new server.
//   - Shutdown broadcasts HTTP/2 GOAWAY (the standard library registers this
//     on the same shutdown that closes the listeners), after which the client
//     opens new streams on a fresh connection to the new server.
//   - responses already in flight keep being served by the old server in the
//     background until they complete or the grace period expires; the fence
//     never waits for or cuts them short.
type drainController struct {
	once sync.Once

	mu     sync.Mutex
	states map[net.Conn]http.ConnState

	// listeners each expose a channel closed once Shutdown has closed that
	// listener and all of its Accept calls have returned.
	listeners []*drainListener

	// hooksDone is closed from the server OnShutdown hook after the
	// half-open connection sweep. Shutdown invokes these hooks (the standard
	// library's HTTP/2 GOAWAY broadcast is one of them) once the listeners are
	// already closed, so reaching it means the graceful shutdown is under way.
	hooksOnce  sync.Once
	hooksDone  chan struct{}
	timedOut   bool

	shutdownDone   chan struct{}
	shutdownDoneMu sync.Mutex
}

func newDrainController() *drainController {
	return &drainController{
		states:    make(map[net.Conn]http.ConnState),
		hooksDone: make(chan struct{}),
	}
}

// wrapListener registers ln with the controller and returns a listener whose
// Close is synchronized with its Accept calls. Accepted connections are left
// untouched on purpose: the wrapper must stay transparent because the standard
// library dispatches TLS HTTP/2 based on the concrete connection type.
func (d *drainController) wrapListener(ln net.Listener) *drainListener {
	dl := &drainListener{Listener: ln, closed: make(chan struct{})}
	d.mu.Lock()
	d.listeners = append(d.listeners, dl)
	d.mu.Unlock()
	return dl
}

// connState is the server ConnState hook. HTTP/1 connections report
// New/Active/Idle/Closed; the HTTP/2 implementation reports Active/Idle.
func (d *drainController) connState(conn net.Conn, state http.ConnState) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if state == http.StateClosed {
		delete(d.states, conn)
		return
	}
	d.states[conn] = state
}

// onServerShutdown is the http.Server OnShutdown callback. Shutdown invokes
// it after it has synchronously closed every listener.
func (d *drainController) onServerShutdown() {
	d.mu.Lock()
	var freshConns []net.Conn
	for conn, state := range d.states {
		if state == http.StateNew {
			freshConns = append(freshConns, conn)
		}
	}
	d.mu.Unlock()

	// drop connections accepted before the fence which never produced a
	// request: nothing is in flight on them, so closing makes the client
	// reconnect to the new instance without losing any response
	for _, conn := range freshConns {
		_ = conn.Close()
	}

	d.hooksOnce.Do(func() { close(d.hooksDone) })
}

// beginDrain starts the graceful shutdown and returns a channel closed when it
// fully completes. It is idempotent.
func (d *drainController) beginDrain(server *http.Server, graceCtx context.Context, logger *zap.Logger) <-chan struct{} {
	d.once.Do(func() {
		d.shutdownDoneMu.Lock()
		d.shutdownDone = make(chan struct{})
		d.shutdownDoneMu.Unlock()

		go func() {
			defer close(d.shutdownDone)
			if err := server.Shutdown(graceCtx); err != nil {
				if cause := context.Cause(graceCtx); cause != nil && err == context.DeadlineExceeded {
					err = cause
				}
				if logger != nil {
					logger.Error("server shutdown", zap.Error(err))
				}
			}
		}()
	})

	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	return done
}

// waitFence blocks until the old server provably stopped accepting new
// connections and disabled further keep-alive requests, or the timeout
// elapses. It never waits for responses already in flight.
func (d *drainController) waitFence(logger *zap.Logger) {
	deadline := time.NewTimer(drainFenceTimeout)
	defer deadline.Stop()

	d.mu.Lock()
	listeners := append([]*drainListener(nil), d.listeners...)
	d.mu.Unlock()

	for _, ln := range listeners {
		select {
		case <-ln.closed:
		case <-deadline.C:
			if logger != nil {
				logger.Error("timed out waiting for old listener to stop accepting",
					zap.Duration("timeout", drainFenceTimeout))
			}
			d.timedOut = true
			return
		}
	}

	// listeners are provably closed; wait briefly for the OnShutdown hooks
	// (HTTP/2 GOAWAY broadcast and the half-open sweep) to run
	select {
	case <-d.hooksDone:
	case <-deadline.C:
		if logger != nil {
			logger.Error("timed out waiting for old server shutdown hooks",
				zap.Duration("timeout", drainFenceTimeout))
		}
		d.timedOut = true
	}
}

// waitShutdownDone blocks until the background shutdown completes. This is
// only used when the process exits, the sole place in-flight responses are
// waited on synchronously.
func (d *drainController) waitShutdownDone() {
	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	if done != nil {
		<-done
	}
}

// drainListener is a net.Listener whose Close is synchronized with in-flight
// Accept calls. http.Server.Shutdown invokes Close synchronously while holding
// its listener lock and only after setting the shutdown flag, so Close
// returning proves both that accepting has stopped and that keep-alive
// admission is now gated by the shutdown flag.
type drainListener struct {
	net.Listener

	closeOnce sync.Once
	closeErr  error

	// acceptors is held while an Accept call is blocked or running.
	acceptors sync.WaitGroup

	// closed is closed once the underlying listener has been closed and all
	// Accept calls have returned.
	closed chan struct{}
}

func (l *drainListener) Accept() (net.Conn, error) {
	l.acceptors.Add(1)
	defer l.acceptors.Done()
	return l.Listener.Accept()
}

// Close is idempotent: Shutdown closes the listener, and server teardown may
// close it again.
func (l *drainListener) Close() error {
	l.closeOnce.Do(func() {
		l.closeErr = l.Listener.Close()
		// once the listener is closed a blocked Accept returns promptly; wait
		// for it so a connection cannot be dispatched after the drain
		l.acceptors.Wait()
		close(l.closed)
	})
	<-l.closed
	return l.closeErr
}

