package caddyhttp

import (
	"context"
	"net"
	"net/http"
	"sync"
	"time"

	"go.uber.org/zap"
)

// drainFenceTimeout bounds how long a configuration switch waits for an old
// server to reach the point at which it provably no longer admits new work.
// Closing the listeners (the strongest guarantee) is synchronous inside
// http.Server.Shutdown and is not subject to this timeout; this only covers
// the bookkeeping performed afterwards. It exists solely so a wedged server
// cannot make POST /load hang forever.
const drainFenceTimeout = 5 * time.Second

// drainController makes the instant an old HTTP server stops admitting new
// connections and requests deterministic across a configuration switch.
//
// http.Server.Shutdown performs the right actions, but their effect only
// becomes observable asynchronously, and Caddy historically waited merely for
// the shutdown goroutine to be scheduled - which could happen before Shutdown
// had closed a single listener. This controller turns that into a fence:
//
//   - every listener is wrapped so Close blocks until each in-flight Accept
//     has returned. http.Server.Shutdown closes its listeners synchronously
//     before doing anything else, so once the OnShutdown hook fires, the old
//     server provably cannot hand out another connection. A new connection to
//     the reused socket therefore always reaches the new server.
//   - Shutdown sets the server's shutdown flag before closing listeners, so
//     by the same point HTTP/1 keep-alives are closed if idle and a response
//     already in flight is the last request its connection serves; the
//     net/http server checks this synchronously before processing any further
//     request, including one already buffered in the connection.
//   - connections that were accepted but never produced a request are closed
//     by the fence: they carry no in-flight response and the client reconnects
//     to the new instance transparently.
//   - Shutdown broadcasts HTTP/2 GOAWAY (after which new multiplexed streams
//     are refused) and, in the background, keeps serving responses that were
//     already in flight until they complete or the grace period expires.
//
// beginDrain starts Shutdown and returns once the admission fence has been
// reached (listeners closed, accepting stopped, half-open connections
// dropped, graceful shutdown under way). In-flight responses are neither
// waited on nor cut short here; the returned channel closes only when the
// background shutdown fully completes (responses finished or grace expired).
type drainController struct {
	once sync.Once

	mu        sync.Mutex
	listeners []*drainListener
	states    map[net.Conn]http.ConnState

	// fenceReached is closed from the http.Server OnShutdown hook, which can
	// only run after Shutdown has synchronously closed every listener - and
	// every wrapped listener Close waits for its Accept calls to return.
	fenceOnce    sync.Once
	fenceReached chan struct{}

	shutdownDone   chan struct{}
	shutdownDoneMu sync.Mutex
}

func newDrainController() *drainController {
	return &drainController{
		states:       make(map[net.Conn]http.ConnState),
		fenceReached: make(chan struct{}),
	}
}

// wrapListener makes Close wait for in-flight Accept calls and registers the
// listener with the controller. The accepted connections themselves are left
// untouched (the wrapper must stay transparent because the standard library
// dispatches TLS HTTP/2 based on the concrete *tls.Conn type).
func (d *drainController) wrapListener(ln net.Listener) *drainListener {
	dl := &drainListener{Listener: ln}
	d.mu.Lock()
	d.listeners = append(d.listeners, dl)
	d.mu.Unlock()
	return dl
}

// connState is the server ConnState hook. HTTP/1 connections report
// New/Active/Idle/Closed; the HTTP/2 implementation reports Active/Idle.
func (d *drainController) connState(conn net.Conn, state http.ConnState) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if state == http.StateClosed {
		delete(d.states, conn)
		return
	}
	d.states[conn] = state
}

// onServerShutdown is registered as the http.Server OnShutdown callback. It
// runs after Shutdown has closed every listener; waiting on the accept groups
// here is therefore already guaranteed to see accepting stopped.
func (d *drainController) onServerShutdown() {
	d.mu.Lock()
	var freshConns []net.Conn
	for conn, state := range d.states {
		if state == http.StateNew {
			freshConns = append(freshConns, conn)
		}
	}
	d.mu.Unlock()

	// drop connections accepted before the fence that never produced a
	// request: nothing is in flight on them, so closing makes the client
	// reconnect to the new instance without losing any response
	for _, conn := range freshConns {
		_ = conn.Close()
	}

	// ensure every wrapped listener has stopped accepting before the fence is
	// considered reached (Shutdown closes them just before invoking this hook)
	d.mu.Lock()
	listeners := append([]*drainListener(nil), d.listeners...)
	d.mu.Unlock()
	for _, ln := range listeners {
		ln.waitAcceptors()
	}

	d.fenceOnce.Do(func() { close(d.fenceReached) })
}

// beginDrain starts the graceful shutdown and returns the channel closed when
// it fully completes. It is idempotent.
func (d *drainController) beginDrain(server *http.Server, graceCtx context.Context, logger *zap.Logger) <-chan struct{} {
	d.once.Do(func() {
		d.shutdownDoneMu.Lock()
		d.shutdownDone = make(chan struct{})
		d.shutdownDoneMu.Unlock()

		go func() {
			defer close(d.shutdownDone)
			if err := server.Shutdown(graceCtx); err != nil {
				if cause := context.Cause(graceCtx); cause != nil && err == context.DeadlineExceeded {
					err = cause
				}
				if logger != nil {
					logger.Error("server shutdown", zap.Error(err))
				}
			}
		}()
	})

	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	return done
}

// waitFence blocks until the old server provably stopped accepting new work,
// or the timeout elapses. It does not wait for in-flight responses.
func (d *drainController) waitFence(logger *zap.Logger) {
	timer := time.NewTimer(drainFenceTimeout)
	defer timer.Stop()
	select {
	case <-d.fenceReached:
	case <-timer.C:
		// reaching here means the OnShutdown hook did not run in time even
		// though Shutdown was started; keep the switch moving and record it
		if logger != nil {
			logger.Error("timed out waiting for old server shutdown fence",
				zap.Duration("timeout", drainFenceTimeout))
		}
	}
}

// waitShutdownDone blocks until the background shutdown of the server
// completes. Used when the process exits, the only place in-flight responses
// are waited on synchronously.
func (d *drainController) waitShutdownDone() {
	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	if done != nil {
		<-done
	}
}

// drainListener is a net.Listener whose Close is synchronized with in-flight
// Accept calls. http.Server.Shutdown invokes Close while holding its own
// listener lock, so by the time Shutdown proceeds every blocked Accept on a
// drained listener has returned and the server can no longer dispatch a new
// connection.
type drainListener struct {
	net.Listener

	closeOnce sync.Once
	closeErr  error

	// acceptors tracks outstanding Accept calls: incremented before Accept
	// blocks and decremented after it returns.
	acceptors sync.WaitGroup
}

func (l *drainListener) Accept() (net.Conn, error) {
	l.acceptors.Add(1)
	defer l.acceptors.Done()
	return l.Listener.Accept()
}

func (l *drainListener) waitAcceptors() { l.acceptors.Wait() }

// Close is idempotent: the drain fence closes the listener through
// http.Server.Shutdown and the server may also close it during teardown.
func (l *drainListener) Close() error {
	l.closeOnce.Do(func() {
		l.closeErr = l.Listener.Close()
	})
	// after the underlying listener is closed, a blocked Accept returns
	// promptly; wait for it so a connection can never be dispatched after the
	// fence considers accepting stopped
	l.acceptors.Wait()
	return l.closeErr
}

