// finishedShutdown tracks the background drain of every HTTP/1/2 and
// HTTP/3 server. The drain keeps serving responses already in flight, so
// it is only awaited synchronously when the process is exiting; a config
// switch returns as soon as the admission fences below are reached.
var finishedShutdown sync.WaitGroup

stopServer := func(server *Server) {
	defer finishedShutdown.Done()

	// possible if server failed to Start
	if server.server == nil || server.drain == nil {
		return
	}

	// beginDrain runs http.Server.Shutdown in the background: it closes
	// the listeners (synchronously inside Shutdown), disables keep-alive
	// admission, broadcasts HTTP/2 GOAWAY and then serves in-flight
	// responses until they finish or the grace period expires.
	done := server.drain.beginDrain(server.server, ctx,
		app.logger.With(zap.Strings("addresses", server.Listen)))

	// Wait here until this server provably stopped accepting new
	// connections and requests. This is the deterministic switch
	// boundary: once it returns, a reused keep-alive connection can only
	// be refused/closed by the old server and any new connection or
	// multiplexed stream reaches the new server - while responses already
	// in flight continue to be served via the background drain.
	server.drain.waitFence(app.logger.With(zap.Strings("addresses", server.Listen)))

	// only a process exit waits for the in-flight responses themselves;
	// otherwise the drain completes asynchronously after we return
	if caddy.Exiting() {
		<-done
	}
}
stopH3Server := func(server *Server) {
	defer finishedShutdown.Done()

	if server.h3server == nil {
		return
	}

	// closing quic listeners won't affect accepted connections now
	// so like stdlib, close listeners first, but keep the net.PacketConns open
	for _, h3ln := range server.quicListeners {
		if err := h3ln.Close(); err != nil {
			app.logger.Error("http3 listener close",
				zap.Error(err))
		}
	}

	if err := server.h3server.Shutdown(ctx); err != nil {
		if cause := context.Cause(ctx); cause != nil && errors.Is(err, context.DeadlineExceeded) {
			err = cause
		}
		app.logger.Error("HTTP/3 server shutdown",
			zap.Error(err),
			zap.Strings("addresses", server.Listen))
	}

	// close the underlying net.PacketConns now
	// see the comment for ListenQUIC
	for _, h3ln := range server.quicListeners {
		if err := h3ln.Close(); err != nil {
			app.logger.Error("http3 listener close socket",
				zap.Error(err))
		}
	}
}

// Start every drain. HTTP/1/2 drains block only until their deterministic
// admission fence is reached (inside stopServer) and then finish in the
// background; HTTP/3 keeps shutting down concurrently as before.
for _, server := range app.Servers {
	finishedShutdown.Add(2)
	go stopServer(server)
	go stopH3Server(server)
}

// if the process is exiting, block here for the grace periods so the
// process does not terminate while responses are still in flight; during
// an ordinary config switch only the much shorter admission fences above
// are awaited before returning
if caddy.Exiting() {
	finishedShutdown.Wait()
}

// run stop callbacks; when exiting the servers are fully shut down by now,
// otherwise they drain in the background. Either way the old handler
// instances are the only owners of these callbacks.
for name, s := range app.Servers {
	for _, stopHook := range s.onStopFuncs {
		if err := stopHook(ctx); err != nil {
			app.logger.Error("server stop hook", zap.String("server", name), zap.Error(err))
		}

