		select {
		case <-ln.closed:
		case <-ctx.Done():
			if logger != nil {
				logger.Error("timed out waiting for old listener to stop accepting",
					zap.Duration("timeout", drainFenceTimeout))
			}
			// listener teardown is the strongest and normally synchronous
			// guarantee; proceed so a wedged server cannot stall the switch
			return
		}
	}

	// listeners are provably closed; wait for the OnShutdown hooks (HTTP/2
	// GOAWAY broadcast and the half-open sweep) to run as well
	select {
	case <-d.hooksDone:
	case <-ctx.Done():
