// drainListener is a net.Listener whose Close is synchronized with in-flight
// Accept calls. http.Server.Shutdown invokes Close synchronously while holding
// its listener lock and only after setting the shutdown flag, so Close
// returning proves both that accepting has stopped and that keep-alive
// admission is now gated by the shutdown flag.
type drainListener struct {
	net.Listener

	closeOnce sync.Once
	closeErr  error

	// acceptors is held while an Accept call is blocked or running.
	acceptors sync.WaitGroup

	// closed is closed once the underlying listener has been closed and all
	// Accept calls have returned.
	closed chan struct{}
}

func (l *drainListener) Accept() (net.Conn, error) {
	l.acceptors.Add(1)
	defer l.acceptors.Done()
	return l.Listener.Accept()
