// onServerShutdown is the http.Server OnShutdown callback. Shutdown invokes
// it after it has synchronously closed every listener.
func (d *drainController) onServerShutdown() {
	d.mu.Lock()
	var freshConns []net.Conn
	for conn, state := range d.states {
		if state == http.StateNew {
			freshConns = append(freshConns, conn)
		}
	}
	d.mu.Unlock()

	// drop connections accepted before the fence which never produced a
	// request: nothing is in flight on them, so closing makes the client
	// reconnect to the new instance without losing any response
	for _, conn := range freshConns {
		_ = conn.Close()
	}

	d.hooksOnce.Do(func() { close(d.hooksDone) })
}

// beginDrain starts the graceful shutdown and returns a channel closed when it
// fully completes. It is idempotent.
func (d *drainController) beginDrain(server *http.Server, graceCtx context.Context, logger *zap.Logger) <-chan struct{} {
	d.once.Do(func() {
		d.shutdownDoneMu.Lock()
		d.shutdownDone = make(chan struct{})
		d.shutdownDoneMu.Unlock()

		go func() {
			defer close(d.shutdownDone)
			if err := server.Shutdown(graceCtx); err != nil {
				if cause := context.Cause(graceCtx); cause != nil && err == context.DeadlineExceeded {
					err = cause
				}
				if logger != nil {
					logger.Error("server shutdown", zap.Error(err))
				}
			}
		}()
	})

	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	return done
}

// waitFence blocks until the old server provably stopped accepting new
// connections and disabled further keep-alive requests, or the timeout
// elapses. It never waits for responses already in flight.
func (d *drainController) waitFence(logger *zap.Logger) {
	ctx, cancel := context.WithTimeout(context.Background(), drainFenceTimeout)
	defer cancel()

	d.mu.Lock()
	serves := append([]<-chan struct{}(nil), d.serves...)
	d.mu.Unlock()

	for _, finished := range serves {
		select {
		case <-finished:
		case <-ctx.Done():
			if logger != nil {
				logger.Error("timed out waiting for old server to stop accepting",
					zap.Duration("timeout", drainFenceTimeout))
			}
			// accepting should stop synchronously once Shutdown closes the
			// listener; proceed rather than stall the whole config switch
			return
		}
	}

	// every Serve loop has returned (listeners provably closed); wait for the
	// OnShutdown hooks (HTTP/2 GOAWAY broadcast and the half-open sweep) too
	select {
	case <-d.hooksDone:
	case <-ctx.Done():
		if logger != nil {
			logger.Error("timed out waiting for old server shutdown hooks",
				zap.Duration("timeout", drainFenceTimeout))
		}
	}
}

// waitShutdownDone blocks until the background shutdown completes. This is
// only used when the process exits, the sole place in-flight responses are
// waited on synchronously.
func (d *drainController) waitShutdownDone() {
	d.shutdownDoneMu.Lock()
	done := d.shutdownDone
	d.shutdownDoneMu.Unlock()
	if done != nil {
		<-done
	}
}

